namespace PortfolioOptimizer.Application.Abstractions;

public sealed record StoredArtifact(string RelativePath, string Sha256, long SizeBytes);

/// <summary>
/// Storage for trained model artifacts. Paths are generated by the store from experiment and version ids – never taken
/// from user input – and are relative to a configured root, so a database row cannot point outside it.
/// </summary>
public interface IModelArtifactStore
{
    Task<StoredArtifact> SaveAsync(Guid experimentId, Guid versionId, byte[] content, CancellationToken ct);

    /// <summary>Reads an artifact. Callers verify <see cref="StoredArtifact.Sha256"/> before deserializing.</summary>
    Task<byte[]> ReadAsync(string relativePath, CancellationToken ct);

    Task DeleteExperimentAsync(Guid experimentId, CancellationToken ct);
}
